        "responsibility": "Chịu trách nhiệm toàn diện về quản trị, kế hoạch phát triển và chất lượng giáo dục; phân công, kiểm tra, đánh giá hoạt động; quản lý đội ngũ, tài chính, tài sản, phối hợp các lực lượng. Sản phẩm: kế hoạch, quyết định, hồ sơ quản lý, báo cáo đánh giá.",
